class Solution {
public:
    int numberOfBeams(vector<string>& bank) {
        long long ans = 0;
        int prev = 0;
        for (const string& row : bank) {
            int cnt = 0;
            for (char c : row) {
                if (c == '1') cnt++;
            }
            if (cnt > 0) {
                ans += (long long)prev * cnt;
                prev = cnt;
            }
        }
        return (int)ans;
    }
};
